WITH filtered AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, GREATEST(discount, shipping_fee) AS greatest_discount_shipping_fee FROM orders WHERE customer_id IS NOT NULL AND customer_id IS NOT NULL) SELECT s.*, latest.payment_paid_at, latest.method FROM filtered s LEFT JOIN LATERAL (SELECT c.paid_at AS payment_paid_at, c.method FROM payments c WHERE c.order_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) latest ON TRUE
